// Generated by Suite Builder from a crawl of the site. What the run prints at its end: the page timings.
// EDIT RULES: do not edit this file; regenerating replaces all of it. The timings themselves are core/Timings.java.
package com.playwrightplayground.tests;

import com.playwrightplayground.tests.core.SiteConfig;
import com.playwrightplayground.tests.core.StepLog;
import com.playwrightplayground.tests.core.TestData;
import com.playwrightplayground.tests.core.Timings;

import java.io.IOException;
import java.nio.charset.StandardCharsets;
import java.nio.file.Files;
import java.nio.file.Path;
import java.time.LocalDateTime;
import java.util.ArrayList;
import java.util.Comparator;
import java.util.HashMap;
import java.util.Locale;
import java.util.List;
import java.util.Map;
import java.util.Optional;
import java.util.TreeMap;
import java.util.stream.Collectors;

import org.junit.platform.engine.TestExecutionResult;
import org.junit.platform.launcher.TestExecutionListener;
import org.junit.platform.launcher.TestIdentifier;
import org.junit.platform.launcher.TestPlan;

/**
 * At the end of the run, printed once: how each kind of test did, the site's first; and its page timings
 * (core/Timings). Written too, as target/report.html (G-130): every test, its kind, how it went and why,
 * and a failed one's evidence (target/failures/), to open in a browser or keep with a pipeline's run.
 */
public final class RunReport implements TestExecutionListener {
    /** The kinds of test in the order a person reads them: the site's, then the suite's own (harness, rules). */
    private static final List<String> KINDS = List.of("http", "links", "smoke", "navigation", "menus", "lists", "seo", "consent", "controls", "stories", "other", "harness", "rules");
    /** Per kind: tests passed, run, and skipped (Checks.assume: what a test needed was not there). */
    private final Map<String, int[]> kinds = new TreeMap<>(Comparator.comparingInt(KINDS::indexOf));

    /** The page a run leaves, beside the evidence it links to. */
    public static final Path REPORT = Path.of("target", "report.html");
    /** Each test as it finished: kind, where (class > test), status, ms, reason. */
    private final List<String[]> rows = new ArrayList<>();
    private final Map<String, Long> started = new HashMap<>();
    private TestPlan plan;

    @Override
    public void testPlanExecutionStarted(TestPlan plan) {
        this.plan = plan;
        RerunOnce.startRun();
        System.out.println(SiteConfig.settings());
    }

    /** Its kind: the first of KINDS among its tags or its class's (a rule's dynamic test has only its class's). */
    private String kindOf(TestIdentifier test) {
        java.util.Set<String> tags = new java.util.HashSet<>();
        for (Optional<TestIdentifier> at = Optional.of(test); at.isPresent(); at = plan.getParent(at.get())) at.get().getTags().forEach(t -> tags.add(t.getName()));
        return KINDS.stream().filter(tags::contains).findFirst().orElse("other");
    }

    @Override
    public synchronized void executionStarted(TestIdentifier test) {
        started.put(test.getUniqueId(), System.currentTimeMillis());
    }

    @Override
    public synchronized void executionFinished(TestIdentifier test, TestExecutionResult result) {
        if (!test.isTest()) return;
        String kind = kindOf(test);
        List<String> names = new ArrayList<>(); // from the class down: the engine above it has no parent
        for (Optional<TestIdentifier> at = Optional.of(test); at.isPresent() && plan.getParent(at.get()).isPresent(); at = plan.getParent(at.get())) names.add(0, at.get().getDisplayName());
        String where = String.join(" > ", names);
        long ms = System.currentTimeMillis() - started.getOrDefault(test.getUniqueId(), System.currentTimeMillis());
        boolean skipped = result.getStatus() == TestExecutionResult.Status.ABORTED;
        String how = skipped ? "skipped" : result.getStatus().name().toLowerCase(Locale.ROOT);
        rows.add(new String[] {kind, where, how, String.valueOf(ms), result.getThrowable().map(StepLog::reason).orElse("")});
        int[] counts = kinds.computeIfAbsent(kind, k -> new int[3]);
        counts[0] += result.getStatus() == TestExecutionResult.Status.SUCCESSFUL ? 1 : 0;
        counts[1]++;
        counts[2] += skipped ? 1 : 0;
    }

    @Override
    public void testPlanExecutionFinished(TestPlan plan) {
        if (!kinds.isEmpty()) System.out.println("\nPassed, by kind (the site's first; harness and rules test the suite itself): " + kinds.entrySet().stream()
                    .map(e -> e.getKey() + " " + e.getValue()[0] + " of " + e.getValue()[1] + skippedOf(e.getValue())).collect(Collectors.joining(", ")));
        String data = TestData.used().entrySet().stream().map(e -> e.getKey() + " gave " + e.getValue()).collect(Collectors.joining("; "));
        if (!data.isEmpty()) System.out.println("Test data used up: " + data);
        String report = Timings.report();
        if (!report.isEmpty()) System.out.println(report);
        writeReport(report, data);
    }

    /** target/report.html: the settings, the kinds, the failures first with their evidence, then every test. */
    private synchronized void writeReport(String timings, String data) {
        rows.sort(Comparator.comparing((String[] r) -> !r[2].equals("failed")).thenComparing(r -> KINDS.indexOf(r[0])));
        StringBuilder html = new StringBuilder("<!doctype html><meta charset=utf-8><title>Test run</title><style>body{font:14px system-ui;margin:2em}"
                + "td,th{padding:.3em .6em;text-align:left;border-bottom:1px solid #ddd}.failed{color:#b00}.skipped{color:#888}</style>"
                + "<h1>Test run, " + LocalDateTime.now().withNano(0) + "</h1><p>" + escape(SiteConfig.settings()) + "</p><h2>By kind</h2><table>");
        kinds.forEach((kind, n) -> html.append("<tr><td>").append(kind).append("<td>").append(n[0]).append(" of ").append(n[1]).append(" passed").append(skippedOf(n)));
        html.append("</table><h2>Tests</h2><table><tr><th>Kind<th>Test<th>How<th>ms<th>Why");
        for (String[] r : rows) {
            Path evidence = Path.of("target", "failures", r[1].substring(0, r[1].indexOf(" > ")));
            String link = r[2].equals("failed") && Files.isDirectory(evidence) ? " (<a href=\"failures/" + escape(evidence.getFileName().toString()) + "/\">evidence</a>)" : "";
            html.append("<tr class=").append(r[2]).append("><td>").append(r[0]).append("<td>").append(escape(r[1])).append("<td>").append(r[2])
                    .append("<td>").append(r[3]).append("<td>").append(escape(r[4])).append(link);
        }
        html.append("</table>").append(data.isEmpty() ? "" : "<h2>Test data used up</h2><p>" + escape(data)).append(timings.isEmpty() ? "" : "<h2>Page timings</h2><pre>" + escape(timings) + "</pre>");
        try {
            Files.createDirectories(REPORT.getParent());
            Files.writeString(REPORT, html, StandardCharsets.UTF_8);
            System.out.println("The run's report: " + REPORT.toAbsolutePath().toUri());
        } catch (IOException e) {
            System.out.println("   note: could not write " + REPORT + ": " + e.getMessage());
        }
    }

    /** " (1 skipped)" when a test of the kind was skipped, saying why; "" otherwise. */
    private static String skippedOf(int[] counts) {
        return counts[2] == 0 ? "" : " (" + counts[2] + " skipped)";
    }

    private static String escape(String text) {
        return text.replace("&", "&amp;").replace("<", "&lt;").replace(">", "&gt;").replace("\"", "&quot;");
    }
}
